Q: How to create Singleton in generic class? A: <p>I've been inspired by that solution <a href="https://stackoverflow.com/questions/29570027/creating-a-generic-singleton">Creating a generic singleton</a></p>
<p>and this worked for me.</p>
<p>Here is the improved version! <strong>(Update to 2026.03.03)</strong></p>
<pre class="lang-swift prettyprint-override"><code>
import Foundation


/// Type-keyed singleton container for ``Store`` lifecycle management.
@frozen @MainActor
public enum Singleton {

  private static var instances = [ObjectIdentifier: Any]()

  /// Returns the cached instance for `T`, or builds and stores a new one.
  ///
  /// - Parameter build: Closure that creates a new instance of `T`.
  /// - Returns: The cached or newly built instance.
  public static func getInstance&lt;T&gt;(build: () throws -&gt; T) rethrows -&gt; T {
    let key = ObjectIdentifier(T.self)
    if let instance = instances[key] as? T {
      return instance
    }
    let instance = try build()
    instances[key] = instance
    return instance
  }

  /// Builds a new instance and replaces any existing one for `T`.
  ///
  /// The previous instance is replaced only *after* the builder succeeds,
  /// so a throwing builder does not leave the container empty for that type.
  ///
  /// - Parameter build: Closure that creates a new instance of `T`.
  /// - Returns: The newly built instance.
  @discardableResult
  public static func replace&lt;T&gt;(build: () throws -&gt; T) rethrows -&gt; T {
    let instance = try build()
    instances[ObjectIdentifier(T.self)] = instance
    return instance
  }

  /// Removes the cached instance for the given type.
  ///
  /// - Parameter valueType: The metatype identifying the instance to remove.
  public static func remove&lt;T&gt;(_ valueType: T.Type) {
    instances.removeValue(forKey: ObjectIdentifier(T.self))
  }

  /// Removes all cached instances.
  ///
  /// - Parameter keepingCapacity: When `true`, retains allocated capacity.
  public static func removeAll(keepingCapacity: Bool = false) {
    instances.removeAll(keepingCapacity: keepingCapacity)
  }
}
</code></pre>
